import { useCallback, useRef } from 'react';
import { motion, useAnimate, type Variants } from 'motion/react';
import { cn } from '@/utils/helpers';

interface PreloaderProps {
  onComplete: () => void;
}

const headlineWords = [
  "Hi👋", "I'm", "Chibueze,", "a", "multidisciplinary",
  "designer", "&", "bioinformatics", "enthusiast.",
];

const ctaWords = ["Use", "the", "tab", "above", "to", "navigate!"];

const containerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.08, delayChildren: 0.15 },
  },
};

const ctaContainerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { delay: 0.15, staggerChildren: 0.08, delayChildren: 0.5 },
  },
};

const wordVariants: Variants = {
  hidden: { y: '110%', opacity: 0, filter: 'blur(4px)' },
  visible: {
    y: 0,
    opacity: 1,
    filter: 'blur(0px)',
    transition: { duration: 0.4, ease: 'easeOut' },
  },
};

export function Preloader({ onComplete }: PreloaderProps) {
  const [maskRef, animate] = useAnimate<HTMLDivElement>();
  const exitStartedRef = useRef(false);

  const runExitSequence = useCallback(async () => {
    if (!maskRef.current) {
      onComplete();
      return;
    }

    await new Promise<void>((resolve) => {
      window.setTimeout(resolve, 800);
    });

    await animate(
      maskRef.current,
      { y: '-100%' },
      { duration: 1.2, ease: [0.87, 0, 0.13, 1] },
    );

    onComplete();
  }, [animate, maskRef, onComplete]);

  const handleTextAnimationComplete = useCallback(() => {
    if (exitStartedRef.current) {
      return;
    }
    exitStartedRef.current = true;
    void runExitSequence();
  }, [runExitSequence]);

  const lastHeadlineIndex = headlineWords.length - 1;
  const lastCtaIndex = ctaWords.length - 1;

  function handleHeadlineWordComplete(index: number) {
    if (index !== lastHeadlineIndex) {
      return;
    }
    if (window.innerWidth < 768) {
      handleTextAnimationComplete();
    }
  }

  function handleCtaWordComplete(index: number) {
    if (index !== lastCtaIndex) {
      return;
    }
    if (window.innerWidth >= 768) {
      handleTextAnimationComplete();
    }
  }

  return (
    <div
      className="fixed inset-0 z-[100] overflow-hidden pointer-events-auto"
      aria-hidden={false}
      aria-busy="true"
      aria-label="Loading"
    >
      <motion.div
        ref={maskRef}
        className="absolute inset-0 animated-gradient flex md:items-center md:justify-center h-[100dvh] px-6"
        initial={{ y: 0 }}
      >
        <h1 className="text-center text-[40px] h-fit md:text-[64px] mt-[50%] md:mt-0 text-gray-300 max-w-[1238px] mx-auto leading-[120%] tracking-tight font-normal">
          <motion.div
            variants={containerVariants}
            initial="hidden"
            animate="visible"
            className="flex flex-wrap justify-center gap-x-1 md:gap-x-2 gap-y-2"
          >
            {headlineWords.map((word, idx) => (
              <div
                key={`head-${idx}`}
                className="overflow-hidden h-[1.2em] flex items-center"
              >
                <motion.span
                  variants={wordVariants}
                  className={cn(
                    'inline-block leading-none',
                    word === 'designer' && 'underline decoration-4 text-black',
                  )}
                  onAnimationComplete={() => handleHeadlineWordComplete(idx)}
                >
                  {word}
                </motion.span>
              </div>
            ))}
          </motion.div>

          <motion.div
            variants={ctaContainerVariants}
            initial="hidden"
            animate="visible"
            className={cn(
              'mt-1 hidden md:flex flex-wrap justify-center gap-x-2 gap-y-1 text-gray-200',
            )}
          >
            {ctaWords.map((word, idx) => (
              <div
                key={`cta-${idx}`}
                className="overflow-hidden h-[1.2em] flex items-center"
              >
                <motion.span
                  variants={wordVariants}
                  className="inline-block leading-none"
                  onAnimationComplete={() => handleCtaWordComplete(idx)}
                >
                  {word}
                </motion.span>
              </div>
            ))}
          </motion.div>
        </h1>
      </motion.div>
    </div>
  );
}
